// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }
    function testFuzz_property(uint256 lockBlock, address actor) public {
        vm.assume(actor != address(0));
        // keep the block number far outside the 256-block blockhash window so the
        // settled answer is 0 and settle() completes without paying out
        lockBlock = bound(lockBlock, 1000, type(uint256).max - 1000);
        vm.roll(lockBlock);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(1)));
        vm.roll(lockBlock + 2);
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
